#!/usr/bin/env bash
# Pause or resume Argo CD auto-sync of the per-cluster Istio CR Applications
# (<cluster>-ossm, generated by the spoke-ossm ApplicationSet) on the hub.
#
# Pausing adds a deny sync window for those Applications to their AppProject.
# Patching the Applications' syncPolicy would not stick: the ApplicationSet
# controller rewrites generated Applications to match its template.
#
# Usage:
#   ./tests/tuning/006-gitops-pause.sh --gitops-context CTX --pause|--resume|--status|--clear
# ci-dry-run: --gitops-context ci-hub --pause
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
# shellcheck disable=SC1091
source "${ROOT}/config/versions.env"
# shellcheck disable=SC1091
source "${ROOT}/tests/lib/common.sh"
# shellcheck disable=SC1091
source "${ROOT}/tests/lib/platform.sh"  # platform_gitops_namespace: the hub's Argo CD namespace

HELPER="${ROOT}/tests/tuning/lib/tuning.py"
# Explicit flags; --resume otherwise takes context and namespace from the state file.
CTX_FLAG=""
NS_FLAG=""
NS_DEFAULT="${TUNING_GITOPS_NAMESPACE:-}"
APPSET="${TUNING_GITOPS_APPSET}"
APP_SUFFIX="ossm"
STATE_FILE="${ROOT}/tests/tuning/results/gitops-pause.json"
ACTION=""
DRY_RUN=0

usage() {
	cat <<EOF
Usage: $(basename "$0") --pause|--resume|--status|--clear [options]

Pause or resume Argo CD auto-sync of the Applications generated by the
${APPSET} ApplicationSet, using a deny sync window on their AppProject.

Options:
  --pause                Add the deny window; record it in --state-file.
  --resume               Remove the window recorded in --state-file.
  --status               List the Applications and their AppProject sync windows.
  --clear                Remove the deny window this tool adds for the Applications the
                         ApplicationSet owns now, whether or not a pause record names it
                         (a run whose results, and so its record, are elsewhere or gone).
  --gitops-context CTX   Hub context running Argo CD (default: \$TUNING_GITOPS_CONTEXT).
  --state-file FILE      Pause record (default: tests/tuning/results/gitops-pause.json).
  --namespace NS         Argo CD namespace (default: \$TUNING_GITOPS_NAMESPACE, ${NS_DEFAULT:-empty};
                         empty: from the hub's platform, openshift-gitops on OpenShift,
                         else argocd: terraform/platform output gitops_namespace). The
                         hub's platform is TEST_PLATFORM (config/options.env) when it is
                         kubernetes or openshift, else asked of the hub.
  --appset NAME          ApplicationSet that owns the Applications (default: ${APPSET}).
  --dry-run              Print what would change; do not touch clusters.
  -h, --help             Show this help.

--resume uses the context and namespace recorded in --state-file; a flag that
names a different one is an error.
EOF
}

while [[ $# -gt 0 ]]; do
	case "$1" in
	--gitops-context | --state-file | --namespace | --appset)
		[[ -n "${2:-}" ]] || die "$1 requires a value"
		case "$1" in
		--gitops-context) CTX_FLAG="$2" ;;
		--state-file) STATE_FILE="$2" ;;
		--namespace) NS_FLAG="$2" ;;
		--appset) APPSET="$2" ;;
		esac
		shift 2
		;;
	--pause | --resume | --status | --clear)
		[[ -z "$ACTION" ]] || die "use only one of --pause, --resume, --status, --clear"
		ACTION="${1#--}"
		shift
		;;
	--dry-run) DRY_RUN=1; shift ;;
	-h | --help) usage; exit 0 ;;
	*) die "unknown option: $1 (try --help)" ;;
	esac
done

platform_validate
[[ -n "$ACTION" ]] || die "one of --pause, --resume, --status, --clear is required"
GITOPS_CTX="${CTX_FLAG:-${TUNING_GITOPS_CONTEXT:-}}"
NS="${NS_FLAG:-$NS_DEFAULT}"
# 1 when --resume targets the context and namespace the pause recorded.
AT_RECORDED=0
if [[ "$ACTION" == resume && -f "$STATE_FILE" ]]; then
	rec_ctx="$(python3 -I "$HELPER" state-get "$STATE_FILE" context)"
	rec_ns="$(python3 -I "$HELPER" state-get "$STATE_FILE" namespace)"
	[[ -z "$CTX_FLAG" || "$CTX_FLAG" == "$rec_ctx" ]] \
		|| die "--gitops-context ${CTX_FLAG} differs from the context recorded in ${STATE_FILE} (${rec_ctx})"
	[[ -z "$NS_FLAG" || -z "$rec_ns" || "$NS_FLAG" == "$rec_ns" ]] \
		|| die "--namespace ${NS_FLAG} differs from the namespace recorded in ${STATE_FILE} (${rec_ns})"
	GITOPS_CTX="$rec_ctx"
	NS="${rec_ns:-$NS}"
	[[ -n "$rec_ns" || -n "$NS_FLAG" ]] && AT_RECORDED=1
fi
[[ -n "$GITOPS_CTX" ]] || die "--gitops-context is required: the hub context that runs Argo CD (or set TUNING_GITOPS_CONTEXT)"

if ((DRY_RUN)); then
	case "$ACTION" in
	pause) echo "[dry-run] ${GITOPS_CTX}: add a deny sync window for the Applications owned by ApplicationSet ${APPSET} in ${NS:-the Argo CD namespace of its platform}; record it in ${STATE_FILE}" ;;
	resume) echo "[dry-run] ${GITOPS_CTX}: remove the sync window recorded in ${STATE_FILE} from ${NS:-the namespace recorded there}" ;;
	status) echo "[dry-run] ${GITOPS_CTX}: list Applications owned by ${APPSET} and their AppProject sync windows" ;;
	clear) echo "[dry-run] ${GITOPS_CTX}: remove the deny sync window this tool adds for the Applications owned by ApplicationSet ${APPSET}, recorded or not" ;;
	esac
	exit 0
fi

KUBECTL=()
resolve_kubectl KUBECTL
if [[ -z "$NS" ]]; then
	NS="$(platform_gitops_namespace "$GITOPS_CTX")" \
		|| die "${GITOPS_CTX}: could not tell the hub's platform to pick its Argo CD namespace; set TUNING_GITOPS_NAMESPACE (argocd, or openshift-gitops on OpenShift)"
	echo "Argo CD namespace on ${GITOPS_CTX}: ${NS} (from its platform; TUNING_GITOPS_NAMESPACE sets it)" >&2
fi
K=("${KUBECTL[@]}" --context="$GITOPS_CTX" -n "$NS")
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

# Fills APPS (names) and PROJECTS (unique AppProject names).
discover_apps() {
	local out name project
	"${K[@]}" get applications.argoproj.io -o json >"$WORK/apps.json" \
		|| die "${GITOPS_CTX}: cannot list Argo CD Applications in ${NS} (wrong --gitops-context?)"
	out="$(python3 -I "$HELPER" apps "$WORK/apps.json" "$APPSET" "$APP_SUFFIX")"
	[[ -n "$out" ]] || die "${GITOPS_CTX}: no Applications owned by ApplicationSet ${APPSET} (or named *-${APP_SUFFIX}) in ${NS}; set TUNING_GITOPS_NAMESPACE to the hub's Argo CD namespace (argocd, or openshift-gitops on OpenShift; --namespace when you run this script yourself)"
	APPS=()
	PROJECTS=()
	while read -r name project; do
		APPS+=("$name")
		[[ " ${PROJECTS[*]} " == *" ${project} "* ]] || PROJECTS+=("$project")
	done <<<"$out"
}

case "$ACTION" in
status)
	discover_apps
	echo "Applications: ${APPS[*]}"
	for p in "${PROJECTS[@]}"; do
		echo "AppProject ${p} syncWindows:"
		"${K[@]}" get appprojects.argoproj.io "$p" -o jsonpath='{.spec.syncWindows}'
		echo ""
	done
	if [[ -f "$STATE_FILE" ]]; then echo "Paused by this tool (state: ${STATE_FILE})"; fi
	;;
pause)
	[[ ! -f "$STATE_FILE" ]] || die "already paused (state file ${STATE_FILE} exists); run --resume first"
	discover_apps
	apps_csv="$(IFS=,; echo "${APPS[*]}")"
	mkdir -p "$(dirname "$STATE_FILE")"
	for p in "${PROJECTS[@]}"; do
		"${K[@]}" get appprojects.argoproj.io "$p" -o json >"$WORK/project.json" \
			|| die "${GITOPS_CTX}: cannot read AppProject ${p}"
		python3 -I "$HELPER" window-add "$WORK/project.json" "$apps_csv" "$WORK/window.json" >"$WORK/patch.json"
		# Record the window before patching so --resume can always find it.
		python3 -I "$HELPER" state-add "$STATE_FILE" "$GITOPS_CTX" "$NS" "$p" "$WORK/window.json"
		"${K[@]}" patch appprojects.argoproj.io "$p" --type=merge --patch-file="$WORK/patch.json" >/dev/null \
			|| die "${GITOPS_CTX}: patching AppProject ${p} failed; nothing paused there (state: ${STATE_FILE})"
		echo "Paused auto-sync for ${apps_csv} (deny sync window on AppProject ${p})"
	done
	;;
resume)
	[[ -f "$STATE_FILE" ]] || die "no pause record at ${STATE_FILE}; nothing to resume"
	projects="$(python3 -I "$HELPER" state-get "$STATE_FILE" projects)"
	keep=0
	for p in $projects; do
		python3 -I "$HELPER" state-get "$STATE_FILE" "window:${p}" "$WORK/window.json"
		"${K[@]}" get appprojects.argoproj.io "$p" -o json >"$WORK/project.json" \
			|| die "${GITOPS_CTX}: cannot read AppProject ${p}"
		rc=0
		python3 -I "$HELPER" window-remove "$WORK/project.json" "$WORK/window.json" >"$WORK/patch.json" || rc=$?
		if ((rc == 3)); then
			if ((AT_RECORDED)); then
				echo "AppProject ${p}: sync window already gone"
			else
				echo "AppProject ${p}: no such window in ${NS}" >&2
				keep=1
			fi
			continue
		fi
		((rc == 0)) || die "building the resume patch for AppProject ${p} failed"
		"${K[@]}" patch appprojects.argoproj.io "$p" --type=merge --patch-file="$WORK/patch.json" >/dev/null \
			|| die "${GITOPS_CTX}: patching AppProject ${p} failed; still paused (state: ${STATE_FILE})"
		echo "Resumed auto-sync (removed the deny sync window from AppProject ${p})"
	done
	if ((keep)); then
		die "kept ${STATE_FILE}: it names no namespace and a window was not found in ${NS}; re-run --resume with --namespace"
	fi
	rm -f "$STATE_FILE"
	;;
clear)
	# The window --pause adds is the same for the same Applications (tuning.py window_for), so it
	# is found without its record.
	discover_apps
	apps_csv="$(IFS=,; echo "${APPS[*]}")"
	python3 -I "$HELPER" window "$apps_csv" "$WORK/window.json"
	for p in "${PROJECTS[@]}"; do
		"${K[@]}" get appprojects.argoproj.io "$p" -o json >"$WORK/project.json" \
			|| die "${GITOPS_CTX}: cannot read AppProject ${p}"
		rc=0
		python3 -I "$HELPER" window-remove "$WORK/project.json" "$WORK/window.json" >"$WORK/patch.json" || rc=$?
		if ((rc == 3)); then
			echo "AppProject ${p}: no deny sync window of this tool for ${apps_csv} (--status lists its windows; one for other Applications, from before a member was added or removed, is removed by hand)"
			continue
		fi
		((rc == 0)) || die "building the patch for AppProject ${p} failed"
		"${K[@]}" patch appprojects.argoproj.io "$p" --type=merge --patch-file="$WORK/patch.json" >/dev/null \
			|| die "${GITOPS_CTX}: patching AppProject ${p} failed; still paused"
		echo "Resumed auto-sync (removed this tool's deny sync window from AppProject ${p})"
	done
	;;
esac
